-- PT116-S3-Q3. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT116-S3-Q3$batch09$ AND q.stimulus=$batch09$In an experiment, tennis players who were told that their performance would be used to assess only the quality of their rackets performed much better than an equally skilled group of tennis players who were told that their tennis-playing talent would be measured.$batch09$ AND q.prompt=$batch09$The situation described above most closely conforms to which one of the following propositions?$batch09$ AND q.correct_choice=$batch09$B$batch09$) THEN RAISE EXCEPTION 'Question changed: PT116-S3-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT116-S3-Q3$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT116-S3-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT116-S3-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Situation$batch09$, $batch09$Two equally skilled groups of tennis players. One was told only their rackets were being assessed. The other was told their talent was being measured. The first group played much better.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$The groups are matched on skill, so the only difference is what they believed was being judged. When players thought their own ability was on the line, they played worse.$batch09$), (2, $batch09$Goal$batch09$, $batch09$People perform better when they don't think their abilities are being judged.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT116-S3-Q3$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$This is the trap, picked by 8%. It sounds right, since being watched can make people nervous. But both groups were being watched. What differed was what the players thought was being evaluated: the racket or themselves.$batch09$), ($batch09$B$batch09$, $batch09$The group that thought only the racket was being judged did better. That's people performing better when they don't believe their abilities are being judged.$batch09$), ($batch09$C$batch09$, $batch09$Both groups were equally skilled, and nothing tells us anyone's confidence.$batch09$), ($batch09$D$batch09$, $batch09$Nobody here assesses their own talent.$batch09$), ($batch09$E$batch09$, $batch09$Nobody is trying to please the testers. E also predicts more effort, while the stimulus is about how well people played.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT116-S3-Q3$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
